  "tips": "龟苓膏冷却过程中不可随意移动容器，否则可能影响成型。；加热时应避免使用大火，防止结块或糊底。；可根据个人口味添加蜂蜜、炼乳或水果食用。；不同品牌龟苓膏粉浓度略有差异，建议参照包装说明调整配比。；--",
