  "tips": "可将部分蘑菇预留作为装饰，提前煎香再添加。；使用鸡高汤代替清水风味更佳，建议控制总液体不超过 300 毫升/份。；喜欢浓汤口感可适当增加面粉和淡奶油用量。；建议现做现吃，不建议冷藏或冷冻保存。；--",
