  "tips": "技术总结；不论什么容器，水的量都是可以使用“指尖量水法”煮出好米饭。；水的多少是能够严重影响一碗好米饭的口感。；南方一般食用江南米，北方一般食用北方大米，江南米会比较细长，而北方大米会比较短且圆。；米饭不同品种的米，不同的水量会极度影响口感。；更多信息请参考使用的电饭煲的说明书。",
